import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { vec3, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // 1. Stage Backdrop: Vertical engineered gradient to guarantee rich dark palette
  const bgGeo = new THREE.PlaneGeometry(7.5, 6.0);

  // TSL Vertical Gradient for background
  const bgGradColor0 = vec3(0x11 / 255, 0x11 / 255, 0x16 / 255);
  const bgGradColor1 = vec3(0x1a / 255, 0x1a / 255, 0x22 / 255);
  const bgColorNode = mix(bgGradColor0, bgGradColor1, uv().y);

  const bgMat = new MeshStandardNodeMaterial({
    colorNode: bgColorNode,
    roughness: 0.9,
    metalness: 0.1
  });

  const bgMesh = new THREE.Mesh(bgGeo, bgMat);
  bgMesh.position.z = -1.5;
  group.add(bgMesh);

  // Subtle localized rim light to hit metal finishes without washing out the dark background
  const lowRimLight = new THREE.DirectionalLight('#ff2a38', 0.8);
  lowRimLight.position.set(-2, 2, 1.5);
  group.add(lowRimLight);

  // 2. Main Panel Container (3.4w x 1.9h)
  const panelWidth = 3.4;
  const panelHeight = 1.9;
  const panelGroup = new THREE.Group();
  group.add(panelGroup);

  // Panel Base Mesh carrying vertical engineered TSL gradient albedo & physical responses
  const panelGeo = new THREE.PlaneGeometry(panelWidth, panelHeight);

  const panelGradColor0 = vec3(0x11 / 255, 0x11 / 255, 0x16 / 255);
  const panelGradColor1 = vec3(0x1a / 255, 0x1a / 255, 0x22 / 255);
  const panelColorNode = mix(panelGradColor0, panelGradColor1, uv().y);

  const panelMat = new MeshPhysicalNodeMaterial({
    colorNode: panelColorNode,
    roughness: 0.6,
    metalness: 0.2,
    clearcoat: 0.1,
    clearcoatRoughness: 0.2
  });

  const panelMesh = new THREE.Mesh(panelGeo, panelMat);
  panelGroup.add(panelMesh);

  // Correctly aligned subtle hairline border (0.006-unit)
  const borderGeo = new THREE.EdgesGeometry(panelGeo);
  const borderMat = new THREE.LineBasicMaterial({ color: 0x26262f });
  const borderMesh = new THREE.LineSegments(borderGeo, borderMat);
  borderMesh.position.z = 0.005;
  panelGroup.add(borderMesh);

  // 3. Typographic Client Quote & Styling
  // Manually formatted strings to guarantee absolutely NO overflow or clipped words at frame boundaries
  const quoteString = "The bezel action alone is\nworth the wait. Nothing else on\nmy wrist feels this considered.";
  const quoteMarkString = "“";
  const attributionString = "M. OKAFOR";
  const captionString = "COLLECTOR SINCE 2019";

  // Oversized Quote Mark (0.62 units tall scale mapping)
  const quoteMarkMesh = ctx.fontAtlas.createText(quoteMarkString, {
    fontSize: 62,
    color: '#ff2a38',
    align: 'left'
  });
  // Seated beautifully with 0.5-unit padding constraints
  quoteMarkMesh.position.set(-1.2, 0.35, 0.04);
  quoteMarkMesh.scale.setScalar(0.01); 
  panelGroup.add(quoteMarkMesh);

  // Client Quote (0.25 units below the mark, translated +0.03 for dramatic raking-light depth)
  const quoteMesh = ctx.fontAtlas.createText(quoteString, {
    fontSize: 20,
    color: '#e8ecf2',
    align: 'left'
  });
  quoteMesh.position.set(-1.2, -0.05, 0.03);
  quoteMesh.scale.setScalar(0.01);
  panelGroup.add(quoteMesh);

  // Accent Rule (led by 0.2w x 0.02h emissive red graphic)
  const ruleGeo = new THREE.PlaneGeometry(0.2, 0.02);
  const ruleMat = new MeshStandardNodeMaterial({
    color: '#ff2a38',
    emissive: '#ff2a38',
    emissiveIntensity: 1.4
  });
  const ruleMesh = new THREE.Mesh(ruleGeo, ruleMat);
  ruleMesh.position.set(-1.1, -0.55, 0.03); // Centered on rule width starts at -1.2
  panelGroup.add(ruleMesh);

  // Client Attribution Text
  const attributionMesh = ctx.fontAtlas.createText(attributionString, {
    fontSize: 13,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 1.2
  });
  attributionMesh.position.set(-1.2, -0.7, 0.03);
  attributionMesh.scale.setScalar(0.01);
  panelGroup.add(attributionMesh);

  // Category Caption Text
  const captionMesh = ctx.fontAtlas.createText(captionString, {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 1.5
  });
  captionMesh.position.set(-1.2, -0.85, 0.03);
  captionMesh.scale.setScalar(0.01);
  panelGroup.add(captionMesh);

  // 4. Entrance Motion Choreography
  const tl = gsap.timeline();

  // Reveal transition for panel
  panelGroup.position.y = -0.2;
  tl.to(panelGroup.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out'
  });

  // Settling motion specifically on the primary quote mark
  quoteMarkMesh.scale.setScalar(0);
  tl.to(quoteMarkMesh.scale, {
    x: 0.01,
    y: 0.01,
    z: 0.01,
    duration: 0.9,
    ease: 'power4.out'
  }, 0.25);

  // Apply visual configurations & primitives
  const primitivesList = config.cinematicPrimitives || [];
  const activePrimitives = [];
  primitivesList.forEach((prim) => {
    if (ctx.primitives[prim.name]) {
      const activePrim = ctx.primitives[prim.name](group, prim.params);
      activePrimitives.push(activePrim);
    }
  });

  // 5. Native Cleanup Hook
  group.userData = {
    cleanup: () => {
      tl.kill();
      activePrimitives.forEach(p => p?.cleanup?.());
      bgGeo.dispose();
      bgMat.dispose();
      panelGeo.dispose();
      panelMat.dispose();
      borderGeo.dispose();
      borderMat.dispose();
      ruleGeo.dispose();
      ruleMat.dispose();
    }
  };

  return group;
}
